Your expense tracker is below: add an item with an amount and category, and the totals and bars update straight away. Entries stay only while this page is open, so nothing is saved after you close it. Set a monthly budget to see how much is left.

```page
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<style>
  body{font-family:system-ui,sans-serif;margin:0;padding:16px;background:#f6f7f9;color:#1c1f24}
  h1{font-size:18px;margin:0 0 12px}
  .card{background:#fff;border-radius:10px;padding:12px;margin-bottom:12px;box-shadow:0 1px 3px rgba(0,0,0,.08)}
  .row{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:8px}
  input,select,button{font:inherit;padding:8px;border:1px solid #cdd2d9;border-radius:8px;background:#fff}
  input{flex:1;min-width:110px}
  button{background:#2563eb;color:#fff;border:0;cursor:pointer}
  button.x{background:none;color:#b42318;padding:2px 8px}
  .total{font-size:24px;font-weight:600}
  .muted{color:#667085;font-size:13px}
  .bar{height:8px;background:#e5e7eb;border-radius:4px;overflow:hidden;margin:3px 0 8px}
  .bar i{display:block;height:100%;background:#2563eb}
  .item{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #eef0f3}
  .over{color:#b42318}
</style>
</head>
<body>
<h1>Monthly expenses</h1>

<div class="card">
  <div class="row">
    <input id="desc" placeholder="What was it for?">
    <input id="amt" type="number" min="0" placeholder="Amount (₹)">
  </div>
  <div class="row">
    <select id="cat">
      <option>Food</option><option>Rent</option><option>Travel</option>
      <option>Bills</option><option>Shopping</option><option>Health</option><option>Other</option>
    </select>
    <button id="add">Add expense</button>
  </div>
</div>

<div class="card">
  <div class="muted">Spent this month</div>
  <div class="total" id="total">₹0</div>
  <div class="row" style="margin-top:8px">
    <input id="budget" type="number" min="0" placeholder="Monthly budget (₹)">
  </div>
  <div class="muted" id="left"></div>
</div>

<div class="card">
  <div class="muted" style="margin-bottom:6px">By category</div>
  <div id="cats"></div>
</div>

<div class="card">
  <div class="muted" style="margin-bottom:6px">All entries</div>
  <div id="list"></div>
</div>

<script>
var items = [];
var $ = function(id){return document.getElementById(id)};
function inr(n){return '₹' + Math.round(n).toLocaleString('en-IN')}
function esc(s){return s.replace(/[&<>"]/g, function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]})}

function render(){
  var sum = items.reduce(function(a,b){return a + b.amt}, 0);
  $('total').textContent = inr(sum);

  var b = parseFloat($('budget').value);
  var left = $('left');
  if (b > 0) {
    var diff = b - sum;
    left.className = diff < 0 ? 'muted over' : 'muted';
    left.textContent = diff < 0 ? 'Over budget by ' + inr(-diff) : inr(diff) + ' left of ' + inr(b);
  } else { left.textContent = ''; }

  var by = {};
  items.forEach(function(i){by[i.cat] = (by[i.cat] || 0) + i.amt});
  var keys = Object.keys(by).sort(function(a,c){return by[c] - by[a]});
  $('cats').innerHTML = keys.length ? keys.map(function(k){
    var pct = sum ? by[k] / sum * 100 : 0;
    return '<div style="display:flex;justify-content:space-between"><span>' + esc(k) + '</span><span>' + inr(by[k]) + '</span></div>' +
           '<div class="bar"><i style="width:' + pct.toFixed(0) + '%"></i></div>';
  }).join('') : '<div class="muted">Nothing yet.</div>';

  $('list').innerHTML = items.length ? items.map(function(i, idx){
    return '<div class="item"><span>' + esc(i.desc) + ' <span class="muted">· ' + esc(i.cat) + '</span></span>' +
           '<span>' + inr(i.amt) + ' <button class="x" data-i="' + idx + '">✕</button></span></div>';
  }).join('') : '<div class="muted">Add your first expense above.</div>';
}

$('add').addEventListener('click', function(){
  var amt = parseFloat($('amt').value);
  if (!(amt > 0)) { $('amt').focus(); return; }
  items.unshift({desc: $('desc').value.trim() || 'Expense', amt: amt, cat: $('cat').value});
  $('desc').value = ''; $('amt').value = '';
  render();
});
$('list').addEventListener('click', function(e){
  var i = e.target.getAttribute('data-i');
  if (i !== null) { items.splice(+i, 1); render(); }
});
$('budget').addEventListener('input', render);
render();
</script>
</body>
</html>
```
